d.heading("4.2 Measurement model", 2)
c = R["cfa"]
LL = [v for k, v in R["loadings"].items() if re.fullmatch(r"(GUI|PCA|UR|VER|AIL|IDQ)\d", k)]; LMIN, LMAX = min(LL), max(LL)
