rows = [(k, str(v["items"]), f"{v['alpha']:.2f}", f"{v['cr']:.2f}", f"{v['ave']:.2f}", f"{v['lmin']:.2f}–{v['lmax']:.2f}") for k, v in REL.items()]
d.table("Table 2. Reliability and convergent validity", ["Construct", "Items", "α", "CR", "AVE", "Loadings"], rows, widths=[1700, 900, 1100, 1100, 1100, 2200])
d.heading("4.3 Structural model", 2)
s = R["sem"]
d.para(f"The full model fitted well: χ²({s['df']:.0f}) = {s['chi2']:.1f}, {pv(s['p'])}; CFI = {s['cfi']:.3f}, TLI = {s['tli']:.3f}, RMSEA = {s['rmsea']:.3f}, SRMR = {s['srmr']:.3f}. Table 3 and Figure 1 give the estimates.")
lab = {"PCA~GUI": ("H1", "GUI → PCA"), "CGz~GUI": ("H2", "GUI → CG"), "UR~GUI": ("H3", "GUI → UR"), "VER~GUI": ("H4", "GUI → VER"), "IDQ~PCA": ("H5", "PCA → IDQ"), "IDQ~CGz": ("H6", "CG → IDQ"), "IDQ~UR": ("H7", "UR → IDQ"), "IDQ~VER": ("H8", "VER → IDQ"), "PCA~INTF": ("H10a", "GUI × FK → PCA"), "CGz~INTF": ("H10b", "GUI × FK → CG"), "UR~INTA": ("H11a", "GUI × AIL → UR"), "VER~INTA": ("H11b", "GUI × AIL → VER"), "IDQ~GUI": ("—", "GUI → IDQ (direct)"), "IDQ~FKz": ("—", "FK → IDQ"), "IDQ~AIL": ("—", "AIL → IDQ")}
rows = [(h, t, m(PA[k]["b"]), f"{PA[k]['se']:.2f}", m(PA[k]["beta"]), pv(PA[k]["p"]).replace("p ", "").replace("= ", "") if PA[k]["p"] >= .001 else "< .001", "Supported" if H.get(h) else "—") for k, (h, t) in lab.items()]
d.table("Table 3. Structural estimates", ["Hyp.", "Path", "b", "SE", "β", "p", "Result"], rows, widths=[800, 2700, 900, 800, 900, 1000, 1500])
d.para(f"GenAI use predicted higher perceived competence ({bz('PCA~GUI')}; H1) and a larger calibration gap ({bz('CGz~GUI')}; H2), more uncritical reliance ({bz('UR~GUI')}; H3) and more verification ({bz('VER~GUI')}; H4). Decision quality was lower when perceived competence ({bz('IDQ~PCA')}; H5), the calibration gap ({bz('IDQ~CGz')}; H6) or uncritical reliance ({bz('IDQ~UR')}; H7) was higher, and higher with verification ({bz('IDQ~VER')}; H8). The direct effect of use on quality was small ({bz('IDQ~GUI')}), consistent with full mediation. Explained variance was R² = {R['r2']['PCA']:.2f} (PCA), {R['r2']['CGz']:.2f} (CG), {R['r2']['UR']:.2f} (UR), {R['r2']['VER']:.2f} (VER) and {R['r2']['IDQ']:.2f} (IDQ).")
d.para(f"Moderation. Financial knowledge weakened the effect of use on perceived competence ({bz('PCA~INTF')}; H10a) and on the calibration gap ({bz('CGz~INTF')}; H10b). AI literacy weakened the effect of use on uncritical reliance ({bz('UR~INTA')}; H11a) and strengthened its effect on verification ({bz('VER~INTA')}; H11b). Interaction effect sizes were small to moderate (f² = {R['f2_int']['PCA']:.3f} for PCA, {R['f2_int']['CGz']:.3f} for CG, {R['f2_int']['UR']:.3f} for UR, {R['f2_int']['VER']:.3f} for VER), typical of interaction effects in non-experimental data.")
d.heading("4.4 Indirect and conditional indirect effects", 2)
rows = []
